    biases: []f64,
    config: DMSNNConfig,
    pub fn init(allocator: mem.Allocator, config: DMSNNConfig, num_inputs: usize) !DMSNNLayer {
        var self = DMSNNLayer{};
        self.config = config;
        self.neurons = try allocator.alloc(SpikingNeuron, config.num_neurons);
        @memset(self.neurons, SpikingNeuron.init());
        self.weights = try allocator.alloc(f64, config.num_neurons * num_inputs);
        @memset(self.weights, 1.0);
        self.biases = try allocator.alloc(f64, config.num_neurons);
        @memset(self.biases, 0.0);
        return self;
    }
    pub fn deinit(self: *DMSNNLayer, allocator: mem.Allocator) void {
        allocator.free(self.neurons);
        allocator.free(self.weights);
        allocator.free(self.biases);
    }
    pub fn forward(self: *DMSNNLayer, input: []const f64, dt: f64, qpu_noise: f64, allocator: mem.Allocator) ![]f64 {
        var outputs = try allocator.alloc(f64, self.config.num_neurons);
        const astro = AstroEmbed{};
        const knots = astro.computeKnots(&astro, @as(f64, @floatFromInt(time.milliTimestamp())));
        var prng = std.rand.DefaultPrng.init(self.config.seed + self.config.current_time);
        var random = prng.random();
        for (outputs[0..], 0..) |*output, i| {
            var sum: f64 = self.biases[i];
            for (input[0..], 0..) |inp, j| {
                const idx = i * input.len + j;
                sum += inp * self.weights[idx];
            }
            self.neurons[i].astro_modulation = knots[i % knots.len];
            self.neurons[i].quantum_noise = qpu_noise + random.float(f64) * 0.01;
            self.neurons[i].update(sum, dt, self.neurons[i].quantum_noise);
            output.* = if (self.neurons[i].membrane_potential > 0.5) 1.0 else 0.0;
        }
        return outputs;
    }
    pub fn backward(self: *DMSNNLayer, grad_output: []const f64, learning_rate: f64) void {
        for (grad_output[0..], self.weights[0..], 0..) |g_out, *w, idx| {
            w.* -= g_out * learning_rate;
        }
    }
};
pub const DMSNN = struct {
    layers: []DMSNNLayer,
    config: DMSNNConfig,
    pub fn init(allocator: mem.Allocator, config: DMSNNConfig, num_inputs: usize) !DMSNN {
        var self = DMSNN{};
        self.config = config;
        self.layers = try allocator.alloc(DMSNNLayer, config.num_layers);
        var prev_size = num_inputs;
        for (self.layers[0..], 0..) |*layer, l| {
            layer.* = try DMSNNLayer.init(allocator, config, prev_size);
            prev_size = config.num_neurons;
        }
        return self;
    }
    pub fn deinit(self: *DMSNN, allocator: mem.Allocator) void {
        for (self.layers) |*layer| {
            layer.deinit(allocator);
        }
        allocator.free(self.layers);
    }
    pub fn forward(self: *DMSNN, input: []const f64, dt: f64, qpu_noise: f64, allocator: mem.Allocator) ![]f64 {
        var current = input;
        for (self.layers) |*layer| {
            var next = try layer.forward(current, dt, qpu_noise, allocator);
            allocator.free(current);
            current = next;
        }
        return current;
    }
    pub fn train(self: *DMSNN, inputs: [][]const f64, targets: []f64, epochs: usize, learning_rate: f64, dt: f64, qpu_noise: f64, allocator: mem.Allocator) !void {
        for (0..epochs) |_| {
            for (inputs, targets) |input, target| {
                var output = try self.forward(input, dt, qpu_noise, allocator);
                var loss: f64 = 0.0;
                for (output, 0..) |out, i| {
                    if (i < targets.len) {
                        loss += (out - target) * (out - target);
                    }
                }
                loss /= @as(f64, @floatFromInt(output.len));
                allocator.free(output);
                const grad = try allocator.alloc(f64, self.layers[self.layers.len - 1].config.num_neurons);
                @memset(grad, -2.0 * (target - 1.0));
                self.layers[self.layers.len - 1].backward(grad, learning_rate);
                allocator.free(grad);
            }
        }
    }
};
